    return text + " " + m.note if m.note else text


# ------------------------------------------------------------------ commands

def dump_json(value) -> str:
    return json.dumps(value, indent=2, ensure_ascii=False) + "\n"


def quote_output(header: str, order, quote, as_json: bool) -> str:
    if as_json:
        return dump_json({
            "order": order.id, "date": order.date.isoformat(), "customer": order.customer,
            "lines": [{"sku": l.sku, "quantity": l.quantity, "unit": str(l.unit),
                       "gross": str(l.gross), "discount": str(l.discount), "net": str(l.net)}
                      for l in quote.lines],
            "subtotal": str(quote.subtotal), "order_discount": str(quote.order_discount),
            "tax": str(quote.tax), "total": str(quote.total)})
    out = [header]
    out += ["%s %d %s %s %s %s" % (l.sku, l.quantity, l.unit, l.gross, l.discount, l.net)
            for l in quote.lines]
    out += ["subtotal %s" % quote.subtotal, "order discount %s" % quote.order_discount,
            "tax %s" % quote.tax, "total %s" % quote.total]
    return "\n".join(out) + "\n"


def lines_out(lines: List[str]) -> str:
    return "".join(l + "\n" for l in lines)


def find_order(orders, token: str):
    order_id = normalise_order_id(token)
    for order in orders:
        if order.id == order_id:
            return order
    raise refuse("order %s is not in orders.txt" % token)


def run(argv: List[str]) -> str:
    command, pos, options, directory = parse_args(argv)
    files = read_files(directory, _NEEDS[command])
    catalog, movements, orders = parse_files(directory, files)
    as_json = bool(options.get("json"))

    if command in ("stock", "low"):
        levels = stock_levels(catalog, movements)
        rows = []
        for sku in sorted(catalog):
            p, onhand = catalog[sku], levels[sku]
            status = stock_status(onhand, p.reorder)
            if command == "stock":
                rows.append({"sku": sku, "name": p.name, "onhand": onhand, "status": status})
            elif status != "ok":
                rows.append({"sku": sku, "onhand": onhand, "reorder": p.reorder,
                             "buy": buy_quantity(onhand, p.reorder)})
        if as_json:
            return dump_json(rows)
        keys = ("sku", "onhand", "status", "name") if command == "stock" else \
            ("sku", "onhand", "reorder", "buy")
        return lines_out([" ".join(str(r[k]) for k in keys) for r in rows])

    if command == "history":
        sku = normalise_sku(pos[0])
        if sku not in catalog:
            raise refuse("unknown SKU %s" % pos[0])
        rows = history(sku, movements)
        if as_json:
            return dump_json([{"date": m.date.isoformat(), "delta": "%+d" % m.quantity,
                               "balance": bal, "note": m.note} for m, bal in rows])
        return lines_out(["%s %+d %d%s" % (m.date.isoformat(), m.quantity, bal,
                                           " " + m.note if m.note else "") for m, bal in rows])

    if command in ("receive", "ship"):
        return add_movement(command, pos, directory, files["m"], catalog, movements)

    if command == "quote":
        order = find_order(orders, pos[0])
        header = "%s %s %s" % (order.id, order.date.isoformat(), order.customer)
        return quote_output(header, order, price_order(order, catalog), as_json)

    if command == "invoice":
        order = find_order(orders, pos[0])
        quote = invoice_order(order, movements, catalog)
        if quote is None:
            raise refuse("nothing has shipped for order %s" % order.id)
        header = "invoice %s %s %s" % (order.id, order.date.isoformat(), order.customer)
        return quote_output(header, order, quote, as_json)

    if command == "fulfil":
        order = find_order(orders, pos[0])
        on = parse_date(pos[1])
        if on < order.date:
            raise refuse("date %s is before the order date %s" % (pos[1], order.date.isoformat()))
        result = fulfil(order, on, movements, next_line_number(files["m"][1]))
        if result.movements:
            append_movements(directory, files["m"][0], result.movements)
        return lines_out(["%s shipped %d backordered %d" % (l.sku, l.shipped, l.backordered)
                          for l in result.lines] + ["status " + result.status])

    return report(options.get("format", "text"), catalog, movements, orders)


def add_movement(command, pos, directory, file, catalog, movements) -> str:
    raw, text = file
    date = parse_date(pos[0])
    sku = normalise_sku(pos[1])
    if sku is None or sku not in catalog:
        raise refuse("unknown SKU %s" % pos[1])
    if not _QTY.fullmatch(pos[2]) or int(pos[2]) < 1:
        raise refuse("bad quantity %r (want a whole number, 1 or more)" % pos[2])
    note = pos[3].strip(" \t") if len(pos) > 3 else ""
    if "\n" in note or "\r" in note:
        raise refuse("note may not contain a line break")
    try:
        note.encode("utf-8")
    except UnicodeEncodeError:
        raise refuse("note is not valid text")
    quantity = int(pos[2]) * (1 if command == "receive" else -1)
    move = Movement(date, sku, quantity, note, next_line_number(text))
    try:
        check_stock(movements + [move])
    except ParseError as err:
        raise refuse("%s: %s" % (_path(directory, _FILES["m"]), err))
    append_movements(directory, raw, [move])
    return format_movement(move) + "\n"


def report(fmt: str, catalog, movements, orders) -> str:
    rows = report_rows(catalog, movements, orders)
    keys = ("order", "date", "customer", "status", "ordered", "shipped", "quoted", "invoiced")
    records = [{"order": r.order, "date": r.date.isoformat(), "customer": r.customer,
                "status": r.status, "ordered": r.ordered, "shipped": r.shipped,
                "quoted": str(r.quoted), "invoiced": str(r.invoiced)} for r in rows]
    if fmt == "json":
        return dump_json(records)
    if fmt == "csv":
        buf = io.StringIO()
        writer = csv.writer(buf, lineterminator="\n")
        writer.writerow(keys)
        for r in records:
            writer.writerow([r[k] for k in keys])
        return buf.getvalue()
    return lines_out(["%s %s %s %s %d/%d %s %s" % (
        r["order"], r["date"], r["customer"], r["status"], r["shipped"], r["ordered"],
        r["quoted"], r["invoiced"]) for r in records])


# ------------------------------------------------------------------- output

def _write(stream, text: str, errors: str) -> None:
    buffer = getattr(stream, "buffer", None)
    if buffer is not None:
        stream.flush()
        buffer.write(text.encode("utf-8", errors))
        buffer.flush()
    else:
        stream.write(text)
        stream.flush()


def _silence_stdout() -> None:
    """Point fd 1 at /dev/null so the interpreter's exit-time flush cannot fail again."""
    try:
        devnull = os.open(os.devnull, os.O_WRONLY)
        os.dup2(devnull, sys.stdout.fileno())
    except (OSError, ValueError, AttributeError):
        pass


def main(argv: Optional[List[str]] = None) -> int:
    args = list(sys.argv[1:] if argv is None else argv)
    try:
        output = run(args)
    except Exit as err:
        try:
            _write(sys.stderr, "stockroom: %s\n" % err.message, "backslashreplace")
        except (OSError, ValueError):
            pass
        return err.code
    try:
        if output:
            _write(sys.stdout, output, "surrogateescape")
    except (OSError, ValueError):
        _silence_stdout()
    return 0
